#!/usr/local/bin/prhm-node
'use strict';
const fs=require('node:fs');
const path=require('node:path');
const crypto=require('node:crypto');
const cp=require('node:child_process');
const ACTION='company_os_dashboard_persian_v1';
const APP_ROOT='/var/lib/prhm-company-os-dashboard/app';
const STATE_DIR='/var/lib/prhm-company-os-dashboard';
const SNAPSHOT=STATE_DIR+'/snapshot.json';
const SERVER=APP_ROOT+'/server.js';
const AUTH='/etc/prhm-company-os-dashboard/auth.json';
const PASS_FILE='/etc/prhm-p0-db-helper/postgres_superuser_password';
const RESULT_DIR='/var/lib/prhm-agent-selfmaint-exec/company-os-dashboard-persian-v1';
const RESULT=RESULT_DIR+'/latest.json';
const NODE='/usr/local/bin/prhm-node';
const DASH_SERVICE='prhm-company-os-dashboard.service';
const TIMER='prhm-company-os-dashboard-collector.timer';
const EXPECTED_SERVER_SHA='de2964c4cb14c135c0bb1b5573b39230ff92de15901c30ab1e48ebaf4c13dd3a';
const FILES=Object.freeze({
 collector:{path:APP_ROOT+'/collector.js',current:'01b684c5d305ca00fde5fa223f0545d34ee109bd1ac49ad20b6ab812c78fc72b',candidate:'300438578d8c87d2be2247f6e08fa4a28a968b856aba803be43f4467ee5a00d6',b64:''},
 app:{path:APP_ROOT+'/public/app.js',current:'b2d0fe6ded54f57b7e1b51de42b88d6ff18c2a79eccc9c5b8d40d255e0a585e1',candidate:'95c68f2d4e99b918f79ec4922cdc45c9b526bc2f6999a264c0790e366dffb34c',b64:''},
 index:{path:APP_ROOT+'/public/index.html',current:'0a386ae24fbc0a513ab7eb48e000297aaa1b470e7557058dea840d31303fc1f7',candidate:'a2e23b6108e427a72a3b092460af9a50dc8a954e386c1f5caa779bb9d2d0ea6c',b64:''},
 css:{path:APP_ROOT+'/public/styles.css',current:'661dcfa380471af64bb50334a3ea92cc9e8421ddf3d494a99448477fc4ddba0f',candidate:'f77b81c2e15647e61531b799370073675d345ca7ca57f2c148828b8fd305305d',b64:''}
});
function fail(m){throw new Error(m)}
function shaBuf(b){return crypto.createHash('sha256').update(b).digest('hex')}
function shaFile(f){return shaBuf(fs.readFileSync(f))}
function run(file,args,opt={}){const r=cp.spawnSync(file,args,{encoding:'utf8',maxBuffer:8*1024*1024,...opt});if(r.error)fail('exec_error:'+file+':'+r.error.message);if(r.status!==0)fail('exec_failed:'+file+':'+r.status+':'+String(r.stderr||'').slice(-1800));return r}
function jsonQuery(sql){if(!/^\s*(SELECT|WITH)\b/i.test(sql))fail('query_not_read_only');const pw=fs.readFileSync(PASS_FILE,'utf8').trim();if(!pw)fail('db_password_empty');const env={...process.env,PGPASSWORD:pw,PGOPTIONS:'-c default_transaction_read_only=on -c statement_timeout=12000 -c lock_timeout=1500'};try{const r=run('/usr/bin/psql',['-X','-At','-v','ON_ERROR_STOP=1','-h','127.0.0.1','-p','55434','-U','leadops_admin','-d','leadops','-c',sql],{env,timeout:30000});const line=String(r.stdout||'').trim().split(/\r?\n/).find(x=>x.trim().startsWith('{'));if(!line)fail('db_json_missing');return JSON.parse(line)}finally{delete env.PGPASSWORD}}
function dbState(){return jsonQuery(`SELECT json_build_object('p0_shadow',(SELECT enabled FROM automation.p0_feature_flags WHERE flag='P0_SHADOW_MODE'),'p0_decision',(SELECT enabled FROM automation.p0_feature_flags WHERE flag='P0_DECISION_ENABLED'),'proposal_auto_send',(SELECT enabled FROM automation.p0_feature_flags WHERE flag='PROPOSAL_AUTO_SEND_ENABLED'),'auto_proposal',(SELECT enabled FROM automation.p0_feature_flags WHERE flag='AUTO_PROPOSAL_ENABLED'),'outbox_total',(SELECT count(*) FROM automation.outbox_events),'outbox_published',(SELECT count(*) FROM automation.outbox_events WHERE status='published'),'bids_total',(SELECT count(*) FROM marketplace.bids),'bids_submitted',(SELECT count(*) FROM marketplace.bids WHERE status='SUBMITTED'),'telegram',(SELECT count(*) FROM automation.telegram_messages))`)}
function assertSafeDb(x){if(x.p0_shadow!==true||x.p0_decision!==false||x.proposal_auto_send!==false||x.auto_proposal!==false)fail('unsafe_feature_flags')}
function serviceState(){const service=String(run('/usr/bin/systemctl',['is-active',DASH_SERVICE]).stdout||'').trim();const timer=String(run('/usr/bin/systemctl',['is-active',TIMER]).stdout||'').trim();const enabled=String(run('/usr/bin/systemctl',['is-enabled',TIMER]).stdout||'').trim();if(service!=='active'||timer!=='active'||enabled!=='enabled')fail('dashboard_runtime_not_healthy');return {service,timer,timer_enabled:enabled}}
function unauthCode(){const r=run('/usr/bin/curl',['-sS','-o','/dev/null','-w','%{http_code}','--max-time','5','-H','Host: agent.prhm.ir','-H','X-Forwarded-Proto: https','http://127.0.0.1:18135/company-os/']);return String(r.stdout||'').trim()}
function candidateBuf(k){const b=Buffer.from(FILES[k].b64,'base64');if(shaBuf(b)!==FILES[k].candidate)fail('candidate_sha_internal_mismatch:'+k);return b}
function validateStaticCandidates(){for(const k of Object.keys(FILES))candidateBuf(k);for(const k of ['collector','app']){const dir=path.join(RESULT_DIR,'syntax');fs.mkdirSync(dir,{recursive:true,mode:0o700});const f=path.join(dir,k+'.js');fs.writeFileSync(f,candidateBuf(k),{mode:0o700});try{run(NODE,['--check',f])}finally{try{fs.unlinkSync(f)}catch{}}}const html=candidateBuf('index').toString('utf8'),app=candidateBuf('app').toString('utf8');for(const x of ['opportunity-details','sources-grid'])if(!html.includes(x))fail('html_contract_missing:'+x);for(const x of ['مناسب برای ارسال پیشنهاد','ارسال‌شده به مشتری','پیش‌نویس آماده‌شده — ارسال نشده','مشاهده آگهی اصلی','منابع بررسی پروژه'])if(!app.includes(x))fail('app_contract_missing:'+x)}
function validateSnapshot(s){if(!s||s.schema_version!=='prhm.company-os-dashboard.snapshot.v2'||s.read_only!==true)fail('snapshot_schema_invalid');if(!Array.isArray(s.sources)||!Array.isArray(s.opportunities)||!Array.isArray(s.decisions))fail('snapshot_arrays_invalid');const codes=new Set(s.sources.map(x=>x&&x.code));for(const c of ['parscoders','karlancer','divar'])if(!codes.has(c))fail('source_missing:'+c);for(const o of s.opportunities){if(!Object.prototype.hasOwnProperty.call(o,'original_url')||!Object.prototype.hasOwnProperty.call(o,'drafts')||!Array.isArray(o.communications))fail('opportunity_contract_invalid');if(o.communications.some(x=>x&&x.delivery_status!=='sent'))fail('communication_state_invalid')}const f=s.safety?.flags||{};if(s.safety?.p0_live!==false||s.safety?.proposal_send!==false||s.safety?.bid_send!==false||s.safety?.auto_send!==false||f.P0_DECISION_ENABLED!==false||f.PROPOSAL_AUTO_SEND_ENABLED!==false||f.AUTO_PROPOSAL_ENABLED!==false)fail('snapshot_safety_invalid');return {schema_version:s.schema_version,sources:s.sources.map(x=>({code:x.code,state:x.state,configured:x.configured,last_checked_at:x.last_checked_at,last_activity_at:x.last_activity_at,discovered_today:x.discovered_today})),opportunities:s.opportunities.length,decisions:s.decisions.length}}
function tempCollectorPreflight(){fs.mkdirSync(RESULT_DIR,{recursive:true,mode:0o700});fs.chmodSync(RESULT_DIR,0o700);const tempRoot=path.join(RESULT_DIR,'temporary-preflight-'+process.pid+'-'+Date.now());fs.mkdirSync(tempRoot,{recursive:true,mode:0o750});const source=candidateBuf('collector').toString('utf8');const anchor="const STATE_DIR='/var/lib/prhm-company-os-dashboard';";if(!source.includes(anchor))fail('collector_state_anchor_missing');const patched=source.replace(anchor,'const STATE_DIR='+JSON.stringify(tempRoot)+';');const file=path.join(tempRoot,'collector-candidate.js');fs.writeFileSync(file,patched,{mode:0o700});try{const r=run(NODE,[file],{timeout:60000});const line=String(r.stdout||'').trim();if(!line.includes('"ok":true'))fail('candidate_collector_output_invalid');const snap=JSON.parse(fs.readFileSync(path.join(tempRoot,'snapshot.json'),'utf8'));return validateSnapshot(snap)}finally{try{fs.rmSync(tempRoot,{recursive:true,force:true})}catch{}}}
function fileMeta(file){const s=fs.statSync(file);return {uid:s.uid,gid:s.gid,mode:s.mode&0o777}}
function atomicWithMeta(file,data,meta){const tmp=file+'.v11-'+process.pid+'-'+Date.now()+'.tmp';fs.writeFileSync(tmp,data,{mode:meta.mode});fs.chownSync(tmp,meta.uid,meta.gid);fs.chmodSync(tmp,meta.mode);fs.renameSync(tmp,file)}
function baseline(){for(const [k,v] of Object.entries(FILES)){if(!fs.existsSync(v.path))fail('live_file_missing:'+k);const a=shaFile(v.path);if(a!==v.current)fail('live_sha_mismatch:'+k+':'+a+':'+v.current)}if(shaFile(SERVER)!==EXPECTED_SERVER_SHA)fail('server_sha_mismatch');if(!fs.existsSync(AUTH))fail('auth_missing');const db=dbState();assertSafeDb(db);const runtime=serviceState();if(unauthCode()!=='401')fail('dashboard_auth_guard_invalid');return {db,runtime,server_sha:shaFile(SERVER),auth_sha:shaFile(AUTH),snapshot_exists:fs.existsSync(SNAPSHOT),snapshot_sha:fs.existsSync(SNAPSHOT)?shaFile(SNAPSHOT):null,metas:Object.fromEntries(Object.entries(FILES).map(([k,v])=>[k,fileMeta(v.path)])),snapshot_meta:fs.existsSync(SNAPSHOT)?fileMeta(SNAPSHOT):null}}
function sameBusinessCounters(a,b){for(const k of ['outbox_total','outbox_published','bids_total','bids_submitted','telegram'])if(Number(a[k])!==Number(b[k]))fail('business_counter_changed:'+k+':'+a[k]+':'+b[k])}
function persist(x){fs.mkdirSync(RESULT_DIR,{recursive:true,mode:0o700});fs.chmodSync(RESULT_DIR,0o700);const tmp=RESULT+'.tmp-'+process.pid;fs.writeFileSync(tmp,JSON.stringify(x,null,2)+'\n',{mode:0o600});fs.chmodSync(tmp,0o600);fs.renameSync(tmp,RESULT)}
function resultBase(){return {schema_version:'prhm.host-action-result.v1',action:ACTION,database_mutation:false,business_mutation:false,p0_live:false,p0_decision:false,proposal_send:false,bid_send:false,auto_send:false,read_only_dashboard:true}}
function preflight(){validateStaticCandidates();const b=baseline();const candidate_snapshot=tempCollectorPreflight();return {...resultBase(),ok:true,preflight_only:true,current_hashes:Object.fromEntries(Object.entries(FILES).map(([k,v])=>[k,v.current])),candidate_hashes:Object.fromEntries(Object.entries(FILES).map(([k,v])=>[k,v.candidate])),server_sha:b.server_sha,auth_sha:b.auth_sha,candidate_snapshot,production_mutation:false}}
function main(){const args=process.argv.slice(2);if(args.length>1||(args.length===1&&args[0]!=='--preflight-only'))fail('unexpected_arguments');if(process.getuid&&process.getuid()!==0)fail('must_run_as_root');if(args[0]==='--preflight-only'){process.stdout.write(JSON.stringify(preflight())+'\n');return}validateStaticCandidates();const b=baseline();const candidate_snapshot=tempCollectorPreflight();const stamp=new Date().toISOString().replace(/[-:.TZ]/g,'').slice(0,14),backup='/var/backups/prhm-company-os-dashboard-persian-v1-'+stamp;fs.mkdirSync(backup,{recursive:true,mode:0o700});for(const [k,v] of Object.entries(FILES)){const dst=path.join(backup,k+'-'+path.basename(v.path)+'.bak');fs.copyFileSync(v.path,dst,fs.constants.COPYFILE_EXCL);fs.chmodSync(dst,0o600)}if(b.snapshot_exists){fs.copyFileSync(SNAPSHOT,path.join(backup,'snapshot.json.bak'),fs.constants.COPYFILE_EXCL);fs.chmodSync(path.join(backup,'snapshot.json.bak'),0o600)}let committed=false;try{for(const [k,v] of Object.entries(FILES))atomicWithMeta(v.path,candidateBuf(k),b.metas[k]);for(const [k,v] of Object.entries(FILES))if(shaFile(v.path)!==v.candidate)fail('post_sha_mismatch:'+k);run(NODE,[FILES.collector.path],{timeout:60000});const liveSnapshot=validateSnapshot(JSON.parse(fs.readFileSync(SNAPSHOT,'utf8')));run('/usr/bin/systemctl',['restart',DASH_SERVICE],{timeout:30000});const runtime=serviceState();if(unauthCode()!=='401')fail('dashboard_auth_guard_post_invalid');if(shaFile(SERVER)!==b.server_sha||shaFile(AUTH)!==b.auth_sha)fail('protected_file_changed');const after=dbState();assertSafeDb(after);sameBusinessCounters(b.db,after);const out={...resultBase(),ok:true,installed:true,updated:true,preflight_only:false,backup_dir:backup,current_hashes:Object.fromEntries(Object.entries(FILES).map(([k,v])=>[k,v.current])),candidate_hashes:Object.fromEntries(Object.entries(FILES).map(([k,v])=>[k,v.candidate])),server_sha:b.server_sha,auth_sha:b.auth_sha,candidate_snapshot,live_snapshot:liveSnapshot,runtime,rollback_verified:false};persist(out);committed=true;process.stdout.write(JSON.stringify(out)+'\n')}finally{if(!committed){let rollbackOk=false;try{for(const [k,v] of Object.entries(FILES)){const src=path.join(backup,k+'-'+path.basename(v.path)+'.bak');atomicWithMeta(v.path,fs.readFileSync(src),b.metas[k])}if(b.snapshot_exists)atomicWithMeta(SNAPSHOT,fs.readFileSync(path.join(backup,'snapshot.json.bak')),b.snapshot_meta);else{try{fs.unlinkSync(SNAPSHOT)}catch(e){if(e.code!=='ENOENT')throw e}}run('/usr/bin/systemctl',['restart',DASH_SERVICE],{timeout:30000});for(const [k,v] of Object.entries(FILES))if(shaFile(v.path)!==v.current)fail('rollback_sha_mismatch:'+k);if(shaFile(SERVER)!==b.server_sha||shaFile(AUTH)!==b.auth_sha)fail('rollback_protected_file_mismatch');sameBusinessCounters(b.db,dbState());rollbackOk=true}catch(rb){process.stderr.write('rollback_failed:'+String(rb&&rb.stack||rb)+'\n')}try{persist({...resultBase(),ok:false,installed:false,updated:false,rollback_verified:rollbackOk,backup_dir:backup})}catch{}}}}
try{main()}catch(e){process.stderr.write(String(e&&e.stack||e)+'\n');process.exit(1)}
